import sys, dis, json
from collections import defaultdict

from reflex.vars.base import LiteralVar, Var
from reflex.vars.sequence import LiteralStringVar, StringVar
import reflex.vars.sequence as seq

TARGET_VARS = [
    'cls','value','_var_type','_var_data','strings_and_vals','offset','m','start','end','serialized_data','var','filtered_strings_and_vals','only_string','literal_strings','s','concat_result'
]
TARGET_SET = set(TARGET_VARS)

code = seq.LiteralStringVar.create.__func__.__code__

instrs = {ins.offset: ins for ins in dis.get_instructions(code)}

last_def = {}
pairs = set()


def tracer(frame, event, arg):
    if event == 'call':
        if frame.f_code is code:
            frame.f_trace_opcodes = True
            # parameters considered defs at function entry
            for name in code.co_varnames[:code.co_argcount + code.co_kwonlyargcount]:
                if name in TARGET_SET and name in frame.f_locals:
                    last_def[name] = frame.f_lineno
            return tracer
        return None
    if frame.f_code is not code:
        return tracer
    if event == 'opcode':
        ins = instrs.get(frame.f_lasti)
        if ins is None:
            return tracer
        op = ins.opname
        name = ins.argval if isinstance(ins.argval, str) else None
        if name in TARGET_SET:
            if op in ('STORE_FAST',):
                last_def[name] = frame.f_lineno
            elif op in ('LOAD_FAST',):
                if name in last_def:
                    pairs.add((name, last_def[name], frame.f_lineno))
    return tracer

sys.settrace(tracer)
user_name = Var(_js_expr='state.user.name', _var_type=str)
status = LiteralVar.create('done').to(StringVar)
encoded_value = f"Hello {user_name}, status {status}!"
result = LiteralStringVar.create(encoded_value)
sys.settrace(None)

out = [
    {'variable': v, 'def_line': d, 'use_line': u}
    for (v,d,u) in sorted(pairs, key=lambda t: (t[0], t[1], t[2]))
]
print(json.dumps(out, indent=2))
print('result', str(result))
